css:
/* ===== Base typography ===== */
body {
    font-family: 'Helvetica Neue', Arial, sans-serif;
    color: #2c2c2c;
    font-size: 12.5px;
    line-height: 1.5;
}

/* ===== Letterhead / logo ===== */
.letter-head {
    text-align: left;
    margin-bottom: 8px;
}
.letter-head img {
    max-height: 60px;
    width: auto;
}
.letter-head + hr {
    border: none;
    border-top: 1px solid #d1d8dd;
    margin: 4px 0 4px;
}

hr {
    margin-top: 0 !important;
    margin-bottom: 0 !important;
}

/* ===== Report title ===== */
h2.text-uppercase {
    font-size: 20px;
    letter-spacing: 2px;
    color: #1a1a2e;
    font-weight: 700;
    margin: 0;
    padding: 10px 0;
}

/* ===== Global row margin reset ===== */
.row {
    margin: 0 !important;

}

/* ===== Patient info block ===== */
.row.section-break {
    background: none;
    border: none;
    border-radius: 0;
    margin: 0 !important;
    box-shadow: none;
    padding: 15px 0;
}

.row.section-break .column-break {
    padding: 0 20px;
}

.row.section-break .column-break:first-child {
    border-right: none;
    padding-left: 0;
}

/* ===== Patient name uppercase ===== */
.row.section-break .column-break:first-child .row:first-child .value {
    text-transform: uppercase;
}

.row.section-break .row {
    display: flex;
    flex-wrap: nowrap;
    align-items: baseline;
    min-height: 0;
    padding: 1px 0;
    border-bottom: none;
    margin-bottom: 0;
    margin-top: 0 !important;
    white-space: nowrap;
}

.row.section-break .col-xs-4 {
    flex: 0 0 110px;
    white-space: nowrap;
}

.row.section-break label {
    color: #2c2c2c;
    font-weight: 400;
    font-size: 12.5px;
    text-transform: none;
    letter-spacing: normal;
    margin: 0;
    white-space: nowrap;
}

.row.section-break label::after {
    content: ":";
}

.row.section-break .value {
    font-weight: 400;
    font-size: 12.5px;
    color: #2c2c2c;
    flex: 1;
    white-space: nowrap;
}

/* ===== Department heading ===== */
h4.text-uppercase,
h4.text-uppercase b,
h4.text-uppercase u,
h4.text-uppercase b u {
    color: #1a1a2e !important;
    text-decoration: underline !important;
}
h4.text-uppercase {
    background: none !important;
    font-size: 13.5px;
    letter-spacing: 1px;
    padding: 0;
    border-radius: 0;
    margin: 14px 0 10px;
    text-align: center;
}

/* ===== Result tables ===== */
table.table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 18px;
}
table.table th {
    background: #f1f2f6;
    color: #1a1a2e;
    text-transform: uppercase;
    font-size: 10.5px;
    letter-spacing: 0.5px;
    padding: 8px 10px;
    border-bottom: 2px solid #dee2e6;
    text-align: left;
}
table.table td {
    padding: 7px 10px;
    border-bottom: 1px solid #f1f2f6;
    vertical-align: top;
}
table.table th:first-child,
table.table td:first-child,
table.table th:nth-child(2),
table.table td:nth-child(2) {
    text-align: left !important;
}
table.table th:nth-child(3),
table.table td:nth-child(3) {
    text-align: right !important;
}

/* Zebra striping for readability on long result sets */
table.table tbody tr:nth-child(even) td {
    background: #fbfbfd;
}

/* Group header row (e.g. "Trials") - bold + underline, no fill */
table.table tr td[colspan="3"] {
    background: transparent;
    font-weight: 700;
    text-decoration: underline;
    text-transform: uppercase;
    font-size: 11px;
    letter-spacing: 0.5px;
    color: inherit;
    padding: 8px 10px 4px;
    border-bottom: none;
}

/* Full-width divider under the group header, on the next data row instead */
table.table tr:has(td[colspan="3"]) + tr td {
    border-top: 1px solid #dee2e6;
}

/* ===== Comments / instructions / legend ===== */
b {
    color: #1a1a2e;
}

/* ===== Signature / footer block ===== */
.text-right h6 {
    margin: 2px 0;
    font-size: 11.5px;
    letter-spacing: 0.5px;
}

/* ===== Print-specific cleanup ===== */
@media print {
    body {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}
